package com.ricozknow.rag; import com.ricozknow.rag.dto.*; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/admin/rag/evaluation") @RequiredArgsConstructor @PreAuthorize("hasRole('ADMIN')") public class RagEvaluationController { private final RagEvaluationService service; @PostMapping("/cases") public Object create(@Valid @RequestBody RagEvalCaseRequest r){return service.create(r);} @PostMapping("/runs") public RagEvalRunResponse run(){return service.run();} @GetMapping("/runs") public List<?> recent(){return service.recent();} }
